const CertificationComponent={render:(content,layout,colorMode,pStyle,lang)=>{const items=SectionUtils.lines(content);if(!items.length)return'';const t=SectionUtils.theme(colorMode,pStyle);const title=lang==='th'?'ประกาศนียบัตร':'Certifications';const body=items.map(l=>{const [name,issuer,year]=SectionUtils.parts(l);return `<div class="extra-card compact"><h4>${name||''}</h4>${issuer?`<p class="extra-sub">${issuer}</p>`:''}${year?`<span class="extra-pill">${year}</span>`:''}</div>`}).join('');return SectionUtils.wrap(SectionUtils.title(title,t)+`<div class="extra-grid three">${body}</div>`,'cert-section')}};
